    return json.dumps(value, sort_keys=True, separators=(",", ":"))

def normalize(record):
    return {
        "key": record["key"],
        "node": record["node"],
        "clock": validate(record["clock"]),
        "value": record.get("value"),
        "deleted": bool(record.get("deleted", False)),
    }

def resolve(records):
    # Deduplicate exact records after canonicalisation of the whole record
    unique = {}
    for row in records:
        record = normalize(row)
        unique[canonical(record)] = record
    versions = list(unique.values())
    # Keep versions that are not strictly dominated by any other version
    frontier = [candidate for candidate in versions if not any(compare(other["clock"], candidate["clock"]) == 1 for other in versions)]
    # Choose winner according to tombstone, node, and value ordering
    winner = max(
        frontier,
        key=lambda row: (
            row["deleted"],
            row["node"],
            canonical(row["value"]),
        ),
    )
    return {
        "key": winner["key"],
        "value": None if winner["deleted"] else winner["value"],
        "deleted": winner["deleted"],
        "clock": joined([row["clock"] for row in versions]),
        "winner": winner["node"],
        "conflict": len(frontier) > 1,
    }

